local function getMonsterNames() --[[ getMonsterNames | Line: 25 | Upvalues: ReplicatedStorage (copy) ]]
	local t = {}
	local MonsterData = ReplicatedStorage:FindFirstChild("MonsterData")

	if MonsterData then
		for k, v in pairs(MonsterData:GetChildren()) do
			table.insert(t, v.Name)
		end
	end

	table.sort(t)

	return t
end

