local function getCardNames() --[[ getCardNames | Line: 51 | Upvalues: ReplicatedStorage (copy) ]]
	local t = {}
	local CardModules = ReplicatedStorage:FindFirstChild("CardModules")

	if CardModules then
		for k, v in pairs(CardModules:GetChildren()) do
			if v:IsA("ModuleScript") then
				table.insert(t, v.Name)
			end
		end
	end

	table.sort(t)

	return t
end

local function getLevelNames() --[[ getLevelNames | Line: 66 | Upvalues: ReplicatedStorage (copy) ]]
	local t = {}
	local LevelNames = ReplicatedStorage:FindFirstChild("LevelNames")

	if LevelNames then
		for k, v in pairs(LevelNames:GetChildren()) do
			if v:IsA("Folder") then
				for k2, v2 in pairs(v:GetChildren()) do
					if v2:IsA("StringValue") then
						table.insert(t, v2.Value)
					end
				end
			end
		end
	end

	table.sort(t)

	return t
end

